"""Read-only original friction failure audit and first-step constrained quadratic reference."""
from pathlib import Path
import hashlib,json
import numpy as np
ROOT=Path(__file__).resolve().parents[2];G=ROOT/'experiments/mujoco_joint_contact_lab/friction'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def mx(a):return float(np.max(np.abs(a))) if np.size(a) else 0.
def rot(q):
    x,y,z,w=(q/np.linalg.norm(q,axis=1,keepdims=True)).T
    return np.stack([1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w),2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w),2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)],axis=-1).reshape(-1,3,3)
def first_step_qp(a,c,cfg,impratio=1):
    """Reduced boundary problem at initial pure slip/spin. No native solver calls.

    Minimize 1/2 f.T(A+R)f + f.T(a_free-a_ref), f=S*N.
    Symmetric initial box slip has a fixed tangent direction; sphere spin has
    only torsion. This is a local first-step oracle, not a trajectory emulator.
    """
    inertia=np.array(c['inertia_diagonal_kg_m2']);N=int(a['ncon'][0]);dim=int(a['contact_dim'][0,0]);J=[];S=np.zeros((N*dim,N));R=[];pos=[]
    for k in range(N):
        fr=a['contact_frame'][0,k];radius=a['contact_pos'][0,k]-a['pre_com'][0];sign=1 if a['contact_geom'][0,k,1]==cfg['dynamic_geom'] else -1
        for j in range(dim):J.append(sign*np.r_[fr[j],np.cross(radius,fr[j])] if j<3 else sign*np.r_[np.zeros(3),fr[0]])
        S[k*dim,k]=1.;slide=cfg['treatment']['body_mu'];tors=c['body_mu_torsional_m'];R.extend([1,1/impratio,1/impratio]+([slide**2/(tors**2*impratio)] if dim==4 else []));pos.extend([a['contact_dist'][0,k]]+[0]*(dim-1))
    J=np.array(J);vel=J@a['body_qd'][0,0];mu=np.array(a['contact_friction'][0,0,:dim-1])
    for k in range(N):
        vv=vel[k*dim+1:(k+1)*dim];norm=np.linalg.norm(mu*vv);direction=mu*mu*vv/norm if norm>0 else np.zeros_like(mu);S[k*dim+1:(k+1)*dim,k]=-direction
    imp=cfg['geom_solimp'][0][0];tc,zeta=cfg['geom_solref'][0];b=2/(imp*tc);K=1/(imp*imp*tc*tc*zeta*zeta);aref=-b*vel-K*imp*np.array(pos);Rn=(1-imp)/imp;A=J@np.diag(np.r_[np.ones(3),1/inertia])@J.T;H=A+np.diag(np.array(R)*Rn);aa=J@np.array([0,0,-9.81,0,0,0])-aref;normal=np.linalg.solve(S.T@H@S,-S.T@aa)
    # For alternative impratio the same boundary assumption may become invalid.
    # This calculation is not claimed as a forecast unless KKT remains valid.
    return {'normal_components_N':normal.tolist(),'normal_total_N':float(normal.sum()),'measured_normal_N':float(a['world_contact_force'][0,2]),'error_N':float(normal.sum()-a['world_contact_force'][0,2]),'fixed_boundary_assumption':'initial pure slip/spin; correct only while force is on same cone boundary','tangent_R_over_normal_R':1/impratio}
def main():
    p=read(G/'protocol.json');rev=read(G/'harness-revisions.json');checks=[];measurements=[];raws={}
    def ck(name,actual,expected,passed):checks.append({'name':name,'actual':actual,'expected':expected,'passed':bool(passed)})
    for f in sorted(G.glob('runs/*/result.json')):
        r=read(f)
        if r['run_id'] in rev['excluded_run_ids']:continue
        assert r['status']=='completed';a=dict(np.load(f.parent/'trajectory.npz'));cfg=read(f.parent/'resolved-config.json');c=next(c for c in p['cases'] if c['id']==r['case']);tag=r['run_id'];raws[(r['case'],r['variant'],r['repeat'])]=a;dt=p['run']['dt_s'];mask=np.arange(16)[None,:]<a['ncon'][:,None];active=mask & (a['contact_efc_address']>=0);positive=(a['world_contact_force'][:,2]>1e-10);inactive=mask & ~active;posmask=mask & (a['contact_dist']>=0);v=a['body_qd'][:,0].astype(float);q=a['body_q'][:,0].astype(float);rotation=rot(q[:,3:]);localw=np.einsum('nji,nj->ni',rotation,v[:,3:]);I=np.array(c['inertia_diagonal_kg_m2']);KE=.5*np.sum(v[:,:3]**2,axis=1)+.5*np.sum(localw**2*I,axis=1);U=9.81*q[:,2];TE=KE+U;peak=int(np.argmax(np.diff(KE)));settled=a['t'][:-1]>=.05
        ck(tag+' archive integrity',len(r['files_sha256']),True,all(sha(f.parent/k)==h for k,h in r['files_sha256'].items()));ck(tag+' frozen protocol',r['protocol_sha256'],sha(G/'protocol.json'),r['protocol_sha256']==sha(G/'protocol.json'));ck(tag+' latest observation code',r['runner_sha256'],rev['new_runner_sha256'],r['runner_sha256']==rev['new_runner_sha256']);ck(tag+' actual ellipse/impratio',cfg['options']['cone'],1,cfg['options']['cone']==1 and cfg['options']['impratio']==1)
        ck(tag+' inactive contacts force zero',mx(a['contact_wrench'][inactive]),0,mx(a['contact_wrench'][inactive])==0);ck(tag+' positive distance excluded',int(posmask.sum()),True,np.all(a['contact_efc_address'][posmask]<0));ck(tag+' no warning',int(a['warning_number'].max()),0,a['warning_number'].max()==0)
        normal_error=mx(v[1:,:3]-v[:-1,:3]-dt*(a['world_contact_force']+np.array([0,0,-9.81])));ck(tag+' force explains acceleration',normal_error,2e-7,normal_error<2e-7)
        ballistic=~positive;ballistic_error=mx((v[1:,2]-v[:-1,2]+9.81*dt)[ballistic]);ck(tag+' zero force flights ballistic',ballistic_error,2e-8,ballistic_error<2e-8)
        qp=first_step_qp(a,c,cfg);ck(tag+' first-step QP normal',abs(qp['error_N']),1e-4,abs(qp['error_N'])<1e-4)
        measure={'case':r['case'],'variant':r['variant'],'repeat':r['repeat'],'run_id':tag,'raw_file':str((f.parent/'trajectory.npz').relative_to(ROOT)),'raw_sha256':sha(f.parent/'trajectory.npz'),'actual_gap_per_geom_m':cfg['geom_gap'],'actual_margin_per_geom_m':cfg['geom_margin'],'actual_impratio':cfg['options']['impratio'],'actual_cone':cfg['options']['cone'],'first_step_qp':qp,'posthoc_analytic_impratio1000_same_boundary':first_step_qp(a,c,cfg,1000),'first_step_normal_N':float(a['world_contact_force'][0,2]),'first_step_vertical_acceleration_mps2':float((v[1,2]-v[0,2])/dt),'first_step_height_change_m':float(q[1,2]-q[0,2]),'settled_active_fraction':float(active[settled].any(axis=1).mean()),'settled_positive_normal_fraction':float(positive[settled].mean()),'settled_mean_normal_N':float(a['world_contact_force'][settled,2].mean()),'maximum_native_solver_iterations':int(a['solver_niter'].max()),'native_warnings':int(a['warning_number'].max()),'max_kinetic_energy_increment_J':float(np.diff(KE)[peak]),'max_kinetic_increment_step':peak,'force_at_max_kinetic_increment_N':a['world_contact_force'][peak].tolist(),'potential_energy_increment_same_step_J':float(np.diff(U)[peak]),'total_energy_increment_same_step_J':float(np.diff(TE)[peak]),'max_total_energy_increment_J':float(np.diff(TE).max()),'force_acceleration_identity_error_mps':normal_error,'ballistic_velocity_identity_error_mps':ballistic_error,'max_surface_distance_m':float(a['contact_dist'][mask].max()),'min_surface_distance_m':float(a['contact_dist'][mask].min()),'notes':'Total mechanical energy is post-hoc diagnosis only; frozen kinetic-energy gate is not replaced.'};measurements.append(measure)
    ck('formal eight',len(measurements),8,len(measurements)==8)
    for c in p['cases']:
        for var in ['A','B']:
            a,b=raws[(c['id'],var,1)],raws[(c['id'],var,2)];diffs={k:mx(a[k]-b[k]) for k in a};ck(c['id']+var+' exact repeat',diffs,0,all(x==0 for x in diffs.values()))
    sources={'newton/_src/solvers/mujoco/solver_mujoco.py':sha(ROOT/'sources/newton-v1.7.0/newton/_src/solvers/mujoco/solver_mujoco.py'),'engine_core_constraint.c':sha(G/'native-source/engine_core_constraint.c'),'engine_collision_driver.c':sha(G/'native-source/engine_collision_driver.c')}
    findings=[{'severity':'explanation','claim':'Initial normal launch is quantitatively explained by the native elliptic-cone regularized constraint objective with moving friction dimensions. Independent initial-state reduced QP matches all four A/B normal totals, including box ~151.7 N. This supports contact/friction model coupling, not an incorrect force sign or gap activation interpretation.','evidence':'first_step_qp fields; core_constraint.c R/KBIP 2187-2218, elliptic R coupling 2268-2278, cone force 3596-3651'},{'severity':'boundary','claim':'Observed iterations <=2 and zero warnings do not certify optimization convergence; originals lack gradient/stop residual histories. However the independent first-step optimum and momentum identity provide stronger evidence than iteration counts that this launch is a model response, not simply too few iterations.'},{'severity':'boundary','claim':'Increasing impratio alone changes friction regularization but does not remove cone coupling, nor guarantee reduced normal force. With an unchanged cone boundary and unchanged reference acceleration, reducing tangential R decreases the reduced quadratic denominator, and can increase first-step normal force. It may still alter later slip/sticking; a new experiment must treat the direction as an unverified hypothesis.'},{'severity':'boundary','claim':'The default geom gap=.1 m produces early candidate contacts; positive distance contacts are inactive and carry exactly zero wrench. Their continued presence is not sustained bearing. First launch creates positive distance, inactive constraint and ballistic return; this repeats as chatter.'},{'severity':'boundary','claim':'A kinetic-energy increase alone under gravity is not proof of solver energy injection. Total mechanical energy (kinetic+mgz) is diagnosed separately at the maximum kinetic increment; the original frozen kinetic gate remains failed when exceeded.'}]
    report={'status':'passed' if all(c['passed'] for c in checks) else 'review_check_failed','purpose':'Audit negative original physical findings, not reclassify them','physical_original_status':'failed_criteria (both cases)','checks':len(checks),'passed_checks':sum(c['passed'] for c in checks),'review_script_sha256':sha(Path(__file__)),'source_sha256':sources,'reviewed_group_files_sha256':{x:sha(G/x) for x in ['protocol.json','runner.py','analyze.py','analysis.json','harness-revisions.json']},'measurements':measurements,'findings':findings,'checks_detail':checks,'excluded_original_attempts':rev['excluded_run_ids'],'no_new_simulation':True}
    Path(__file__).with_suffix('.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({'status':report['status'],'passed':report['passed_checks'],'checks':report['checks'],'measurements':[{k:m[k] for k in ['case','variant','repeat','first_step_qp','max_kinetic_energy_increment_J','max_kinetic_increment_step','force_at_max_kinetic_increment_N','potential_energy_increment_same_step_J','total_energy_increment_same_step_J','max_total_energy_increment_J']} for m in measurements if m['repeat']==1],'failures':[c for c in checks if not c['passed']]},ensure_ascii=False))
if __name__=='__main__':main()
